import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container – position/rotation/scale are applied by the adapter
  const root = new Group();

  // --------------------------------------------------------------------------------
  // 1️⃣  Sprite plane (billboarded)
  // --------------------------------------------------------------------------------
  // Atlas region aspect – fallback to 1 if not provided
  const atlasRegion = config.atlasRegion ?? { width: 512, height: 320 };
  const aspect = atlasRegion.width / atlasRegion.height || 1;

  const planeGeom = new PlaneGeometry(aspect, 1);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    toneMapped: false,
  });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture (single region of an atlas; no offset handling required here)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Simple billboard behaviour – face the camera each render frame
  planeMesh.onBeforeRender = (renderer, scene, camera) => {
    planeMesh.quaternion.copy(camera.quaternion);
  };

  // --------------------------------------------------------------------------------
  // 2️⃣  Text headline (if any)
  // --------------------------------------------------------------------------------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of textItems) {
    // Only support plain strings; ignore roles we don't need for this spec
    const content = typeof item === 'string' ? item : item.text ?? '';
    const opts = {
      fontSize: item?.typography?.fontSize ?? 96,
      color: item?.role === 'headline' ? config.visual?.colors?.paper ?? '#e8ecf2' : '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(content, opts);
    // Position the text just above the sprite plane
    txtObj.position.set(0, 0.6, 0.01);
    root.add(txtObj);
    textObjects.push(txtObj);

    // Make the text billboard as well
    txtObj.onBeforeRender = (renderer, scene, camera) => {
      txtObj.quaternion.copy(camera.quaternion);
    };
  }

  // --------------------------------------------------------------------------------
  // 3️⃣  Apply cinematic primitives (none for this node)
  // --------------------------------------------------------------------------------
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name]?.(root, prim.params);
      if (handler) primitiveHandles.push(handler);
    }
  }

  // --------------------------------------------------------------------------------
  // 4️⃣  Cleanup & handlers container
  // --------------------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose plane resources
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose any created text resources
    for (const txt of textObjects) {
      root.remove(txt);
      txt.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }

    // Kill any GSAP timelines that might have been created (none in this node)
    gsap.globalTimeline.clear();
  };

  return root;
}
